\newcommand{\gtop}{\top}
\newcommand{\gbot}{\bot}
\newcommand{\tv}{\mathbf{t}}
\newcommand{\fv}{\mathbf{f}}
\newcommand{\lek}{\le_k}
\newcommand{\tleq}{\le_t}
\newcommand{\FOUR}{\mathbf{FOUR}}
\newcommand{\clo}[1]{\overline{#1}}
\newcommand{\intr}{\operatorname{int}}
\DeclareMathOperator{\bd}{\partial}

\title{Dream Logic: Interlaced Bilattices, Paraconsistent Consequence, and the Topology of Coexisting Contradictions}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\begin{abstract}
We develop the mathematics of \emph{dream logic}: a framework for reasoning in which contradictions can coexist without trivializing the system (paraconsistency), statements may be neither true nor false (paracompleteness), and conclusions may be withdrawn as premises grow (non-monotonicity). The framework rests on three interlocking pillars. First, we exhibit the full \textbf{interlaced bilattice} $\FOUR$ on the four Belnap--Dunn truth values, equipping the carrier with two bounded lattice orders---a \emph{truth} order and a \emph{knowledge} order---proving the four interlacing laws that make them cohere, and establishing negation as a truth-order anti-automorphism / knowledge-order automorphism together with its dual, conflation. Second, we lift this algebra to a genuine propositional \textbf{consequence relation} valued in $\FOUR$, prove it satisfies the Tarskian structural rules (reflexivity, weakening, cut) and the lattice/De Morgan laws, and prove that explosion, excluded middle, and non-contradiction all fail. Third, we give a \textbf{topological semantics} over an arbitrary topological space in which the paraconsistent negation is the closure of the complement, and prove a sharp criterion: a closed proposition harbours a coexisting contradiction if and only if it is not open. Impossible objects (gluts) are exactly boundary points, and the failure of arbitrary unions of closed sets to be closed is exhibited as the structural root of non-monotonicity.
\end{abstract}
\maketitle

\section{Introduction}
Classical logic validates \emph{explosion} (ex contradictione quodlibet): from $p$ and $\neg p$ an arbitrary $q$ follows, so a single inconsistency renders a theory trivial. Yet human reasoning, inconsistent databases, conflicting legal codes, and---vividly---dream cognition tolerate local contradictions while reasoning sensibly. \textbf{Paraconsistent} logics are those in which explosion fails.

We formalize a paraconsistent, paracomplete, non-monotone logic---\emph{dream logic}---organized around three questions: (1) the minimal algebra of truth values supporting coexisting contradictions and revisable belief; (2) whether that algebra induces a genuine consequence relation in which contradictions fail to explode; and (3) where contradictions come from. Our answers are the interlaced bilattice $\FOUR$ (\S3), a $\FOUR$-valued Tarskian yet non-explosive consequence relation (\S4), and a closed-set topological semantics in which gluts are exactly boundary points (\S5).

\section{Preliminaries}
A \emph{partial order} is reflexive, antisymmetric, transitive. A \emph{bounded lattice} has binary meets ($\wedge$) and joins ($\vee$) and a least and greatest element. For a space $X$ we write $\clo{S}$ for closure, $\intr(S)$ for interior, $S^c$ for complement, and $\bd S = \clo{S}\setminus\intr(S)$ for the frontier. A set is \emph{clopen} if closed and open.

\section{The interlaced bilattice $\FOUR$}

\subsection{Carrier and the two orders}
Let $\FOUR=\{\tv,\fv,\gtop,\gbot\}$ read as \emph{true only}, \emph{false only}, \emph{both} (a \textbf{glut}: true and false at once---an impossible object), and \emph{neither} (a \textbf{gap}: undetermined).

\begin{definition}[Truth order]
$a\tleq b$ iff $a=\fv$, or $b=\tv$, or $a=b$: bottom $\fv$, top $\tv$, with $\gtop,\gbot$ incomparable in the middle.
\end{definition}
\begin{definition}[Knowledge order]
$a\lek b$ iff $a=\gbot$, or $b=\gtop$, or $a=b$: bottom $\gbot$, top $\gtop$, with $\tv,\fv$ incomparable.
\end{definition}
\begin{proposition}
Both $\tleq$ and $\lek$ are partial orders.
\end{proposition}
\begin{proof}[Proof sketch]
Reflexivity is the third disjunct; transitivity and antisymmetry are verified by exhausting the sixteen ordered pairs in each case, the incomparable middle pairs forcing equality.
\end{proof}

\subsection{The four operations}
The truth lattice carries \emph{conjunction} $\wedge$ and \emph{disjunction} $\vee$; the knowledge lattice carries \emph{consensus} $\otimes$ (retain what both agree on) and \emph{gullibility} $\oplus$ (accept from either). Representatively,
\[ \gtop\wedge\gbot=\fv,\quad \gtop\vee\gbot=\tv,\quad \tv\otimes\fv=\gbot,\quad \tv\oplus\fv=\gtop. \]

\begin{theorem}[Lattice structure]
$\wedge,\vee$ are glb/lub for $\tleq$; $\otimes,\oplus$ are glb/lub for $\lek$. Moreover $\fv\tleq x\tleq\tv$ and $\gbot\lek x\lek\gtop$ for all $x$.
\end{theorem}
\begin{proof}[Proof sketch]
For each operation prove the projection laws and universal property by case analysis over the finite carrier; the bounds are immediate.
\end{proof}
\begin{corollary}
Each of $\wedge,\vee,\otimes,\oplus$ is commutative, associative, idempotent, and satisfies absorption, e.g. $a\wedge(a\vee b)=a$ and $a\otimes(a\oplus b)=a$.
\end{corollary}

\subsection{Interlacing}
\begin{theorem}[Interlacing laws]
Each operation is monotone in the other order:
\[
\begin{aligned}
a\lek b,\ c\lek d &\Rightarrow (a\wedge c)\lek(b\wedge d), &
a\lek b,\ c\lek d &\Rightarrow (a\vee c)\lek(b\vee d),\\
a\tleq b,\ c\tleq d &\Rightarrow (a\otimes c)\tleq(b\otimes d), &
a\tleq b,\ c\tleq d &\Rightarrow (a\oplus c)\tleq(b\oplus d).
\end{aligned}
\]
\end{theorem}
\begin{proof}[Proof sketch]
A finite monotonicity check over the carrier for both arguments.
\end{proof}
These are exactly the axioms of an \textbf{interlaced bilattice}; $\FOUR$ is the smallest nontrivial such structure.

\subsection{Negation and conflation}
\begin{definition}
\emph{Negation} $\neg$ swaps $\tv\leftrightarrow\fv$ and fixes $\gtop,\gbot$. \emph{Conflation} $c$ swaps $\gtop\leftrightarrow\gbot$ and fixes $\tv,\fv$.
\end{definition}
\begin{theorem}[Negation]
$\neg$ is an involution that reverses $\tleq$ and preserves $\lek$; hence $\neg(a\wedge b)=\neg a\vee\neg b$, $\neg(a\vee b)=\neg a\wedge\neg b$, and $\neg$ is a homomorphism of the knowledge lattice.
\end{theorem}
\begin{theorem}[Conflation]
$c$ is an involution that reverses $\lek$ and preserves $\tleq$; it is a truth-lattice homomorphism with $c(a\otimes b)=c\,a\oplus c\,b$, $c(a\oplus b)=c\,a\otimes c\,b$, and $\neg(c\,a)=c(\neg a)$.
\end{theorem}
\begin{proof}[Proof sketch]
Involution, order equivalences, and the identities are verified over the finite carrier.
\end{proof}

\subsection{Algebraic paraconsistency}
Call $a$ \textbf{designated} iff $a\in\{\tv,\gtop\}$.
\begin{theorem}[Designated filter]
$\{\tv,\gtop\}$ contains $\tv$, is upward closed in $\tleq$, and closed under $\wedge$.
\end{theorem}
\begin{theorem}[Paraconsistency]
For $a=\gtop$, $a\wedge\neg a$ is designated yet $a\wedge\neg a\not\tleq\fv$, and $\fv$ is undesignated: a designated contradiction does not entail everything.
\end{theorem}
\begin{theorem}[Paracompleteness]
For $a=\gbot$, $a\vee\neg a$ is not designated: excluded middle fails.
\end{theorem}

\section{The paraconsistent consequence relation}
\begin{definition}[Formulas]
Over an atom type $V$: $\varphi ::= p \mid \neg\varphi \mid \varphi\wedge\psi \mid \varphi\vee\psi$, $p\in V$.
\end{definition}
\begin{definition}[Valuation, consequence]
A valuation $v:V\to\FOUR$ evaluates formulas via the operations of \S3. A formula is \emph{satisfied} by $v$ when its value is designated, and $\Gamma\vDash\varphi$ iff every valuation satisfying all of $\Gamma$ satisfies $\varphi$.
\end{definition}
\begin{theorem}[Tarskian structure]
$\vDash$ satisfies reflexivity ($\varphi\in\Gamma\Rightarrow\Gamma\vDash\varphi$), weakening ($\Gamma\subseteq\Delta,\ \Gamma\vDash\varphi\Rightarrow\Delta\vDash\varphi$), and cut ($\Gamma\vDash\varphi$ and $\Gamma\cup\{\varphi\}\vDash\psi\Rightarrow\Gamma\vDash\psi$).
\end{theorem}
\begin{theorem}[Connectives]
$\vDash$ validates $\wedge$-introduction, both $\wedge$-eliminations, both $\vee$-introductions, and De Morgan $\neg(\varphi\wedge\psi)\vDash\neg\varphi\vee\neg\psi$.
\end{theorem}
\begin{proof}[Proof sketch]
Each rule reduces to the designated-filter properties and glb/lub laws; De Morgan is the pointwise identity $\neg(a\wedge b)=\neg a\vee\neg b$.
\end{proof}
\begin{theorem}[Explosion fails]
For distinct atoms $p\ne q$, $\{p,\neg p\}\not\vDash q$.
\end{theorem}
\begin{proof}
Take $v$ with $q\mapsto\fv$ and all else $\mapsto\gtop$: both premises are designated, the conclusion is $\fv$.
\end{proof}
\begin{theorem}[Excluded middle and non-contradiction fail]
$\varnothing\not\vDash\varphi\vee\neg\varphi$ and $\varnothing\not\vDash\neg(\varphi\wedge\neg\varphi)$.
\end{theorem}
\begin{proof}
The constant $\gbot$ valuation leaves both formulas at $\gbot$, undesignated.
\end{proof}

\section{Topological semantics: gluts as boundaries}
Fix a space $X$; a proposition is $A\subseteq X$.
\begin{definition}
$\neg A := \clo{A^c}$, the closure of the complement.
\end{definition}
\begin{proposition}
$\neg A$ is always closed.
\end{proposition}
\begin{theorem}[Excluded middle survives]
$A\cup\neg A=X$ for every $A$.
\end{theorem}
\begin{proof}
If $x\notin A$ then $x\in A^c\subseteq\clo{A^c}=\neg A$.
\end{proof}
\begin{theorem}[Gluts are boundary points]
For closed $A$, $A\cap\neg A=\bd A$.
\end{theorem}
\begin{proof}
$\neg A=\clo{A^c}=(\intr A)^c$, so $A\cap\neg A=A\setminus\intr A=\clo A\setminus\intr A=\bd A$.
\end{proof}
\begin{theorem}[Double-negation elimination]
For closed $A$, $\neg\neg A\subseteq A$.
\end{theorem}
\begin{proof}
$\neg\neg A=\clo{(\clo{A^c})^c}=\clo{\intr A}\subseteq\clo A=A$.
\end{proof}
\begin{theorem}[Paraconsistency criterion]
For closed $A$, $A\cap\neg A\ne\varnothing \iff A$ is not open; equivalently $A$ is glut-free iff clopen.
\end{theorem}
\begin{proof}
$A\cap\neg A=\bd A$ is empty iff the closed set $A$ is clopen.
\end{proof}
\begin{theorem}[Non-isolated points are impossible objects]
In a $T_1$ space, if $\{p\}$ is not open then $\{p\}\cap\neg\{p\}\ne\varnothing$.
\end{theorem}
\begin{theorem}[Structural root of non-monotonicity]
In a $T_1$ space, if $x_n\ne p$ for all $n$ and $x_n\to p$, then each $\{x_n\}$ is closed but $\bigcup_n\{x_n\}$ is not.
\end{theorem}
\begin{proof}
Singletons are closed in $T_1$; $p$ lies in the closure of the union, but not in the union, so the union is not closed.
\end{proof}
Each $\{x_n\}$ is a settled proposition; their unbounded union loses its limit point and fails to be settled---exactly non-monotonicity: enlarging premises withdraws a conclusion.
\begin{theorem}[Degeneration to classical logic]
Every closed proposition is glut-free iff every closed set of $X$ is open.
\end{theorem}

\section{Algorithms, applications, discussion}
Finiteness of $\FOUR$ makes all algebraic and semantic claims decidable: (i) tabulate operations and verify laws by checking $\le 4^k$ tuples; (ii) decide $\Gamma\vDash\varphi$ over $n$ atoms by enumerating $4^n$ valuations, a sound and complete decision procedure; (iii) detect topological gluts on a finite space by computing $\bd A=A\cap\neg A$. Applications include inconsistency-tolerant databases (contradictory records take value $\gtop$ without global collapse), belief revision and default reasoning (the gap $\gbot$ and the non-monotonicity theorem), logics of vagueness (borderline cases are literally boundary points), and multi-source fusion ($\otimes$ conservative, $\oplus$ credulous). The three pillars reinforce one another: the algebra supplies the semantic space, the consequence relation shows it yields a genuine logic, and the topology explains the origin of gluts, locating classical logic as the boundary-free degenerate limit.

\section{Future directions}
(1) Bundle $\FOUR$ as an algebraic typeclass and prove the representation theorem: every interlaced bilattice embeds in $L\odot L$, with $\FOUR=2\odot 2$. (2) Prove soundness and completeness of a proof system for the $\neg/\wedge/\vee$ fragment against the $\FOUR$-semantics (first-degree entailment). (3) Lift value-level belief retraction to a non-monotonic operator $\Gamma\mathrel{|\!\sim}\varphi$ and prove genuine non-monotonicity with monotone core $\vDash$. (4) Characterize which bilattices arise as $(\text{closed sets},\neg)$ of a space. (5) Replace the base lattice by $[0,1]$ for a fuzzy dream logic $[0,1]\odot[0,1]$ with a continuum of gluts.

\section{Conclusion}
Dream logic is a mathematics that can hold a contradiction without breaking: a four-valued interlaced bilattice, a Tarskian yet non-explosive consequence relation, and a topological semantics where impossible objects are exactly boundary points and belief retraction is the failure of infinite unions of closed sets to stay closed.

