from typing import Dict, FrozenSet, Set, Tuple

Region = FrozenSet[int]

class FiniteTopology:
    """A finite topological space specified by its open sets."""
    def __init__(self, points: Set[int], opens: Set[Region]) -> None:
        self.points: Region = frozenset(points)
        self.opens: Set[Region] = set(opens)

    def closure(self, a: Region) -> Region:
        result = self.points
        for o in self.opens:
            c = self.points - o           # a closed set
            if a <= c:
                result = result & c        # intersect all closed supersets
        return result

    def pneg(self, a: Region) -> Region:
        """Paraconsistent negation = closure of complement."""
        return self.closure(self.points - a)

    def frontier(self, a: Region) -> Region:
        return a & self.pneg(a)

def classify(topo: FiniteTopology, a: Region) -> Dict[str, object]:
    """Classify a closed proposition as classical (clopen) or glutty."""
    is_open = a in topo.opens
    is_closed = (topo.points - a) in topo.opens
    glut = topo.frontier(a)
    return {
        "closed": is_closed,
        "open": is_open,
        "glut_points": sorted(glut),
        "paraconsistent": bool(glut),   # nonempty glut <=> closed but not open
    }

